options.formula:
IF(
  FIND("expires=", {Bypass URL}),
  DATETIME_PARSE(
    LEFT(
      SUBSTITUTE(SUBSTITUTE(MID({Bypass URL}, FIND("expires=", {Bypass URL}) + 8, 40), "%3A", ":"), "%3a", ":"),
      24
    ),
    "YYYY-MM-DDTHH:mm:ss.SSSZ"
  )
)

IF(
  {Application ID Key} = BLANK(),
  "",
  "https://aurixasystems.com.au/schedule-strategic-review?ref=" & {Application ID Key}
)
